CREATE SCHEMA IF NOT EXISTS veloryz_studio;
REVOKE ALL ON SCHEMA veloryz_studio FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA veloryz_studio TO service_role;
SET LOCAL search_path = veloryz_studio, pg_catalog;
CREATE TABLE IF NOT EXISTS "cms_admins" (
	"user_id" text PRIMARY KEY NOT NULL,
	"email" text NOT NULL,
	"created_at" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "cms_history" (
	"id" text PRIMARY KEY NOT NULL,
	"revision" integer NOT NULL,
	"payload" text NOT NULL,
	"summary" text NOT NULL,
	"actor" text NOT NULL,
	"created_at" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "cms_media" (
	"id" text PRIMARY KEY NOT NULL,
	"storage_key" text NOT NULL,
	"filename" text NOT NULL,
	"mime" text NOT NULL,
	"size" integer NOT NULL,
	"archived" integer DEFAULT 0 NOT NULL,
	"actor" text NOT NULL,
	"created_at" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "cms_state" (
	"id" integer PRIMARY KEY NOT NULL,
	"published" text NOT NULL,
	"draft" text NOT NULL,
	"published_version" integer DEFAULT 0 NOT NULL,
	"draft_version" integer DEFAULT 0 NOT NULL,
	"updated_at" text NOT NULL
);

CREATE TABLE IF NOT EXISTS "studio_enquiries" (
	"id" text PRIMARY KEY NOT NULL,
	"reference" text NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"phone" text NOT NULL,
	"service" text NOT NULL,
	"budget" text NOT NULL,
	"preferred_date" text NOT NULL,
	"preferred_time" text NOT NULL,
	"company" text NOT NULL,
	"message" text NOT NULL,
	"status" text DEFAULT 'new' NOT NULL,
	"notes" text DEFAULT '' NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"fingerprint" text NOT NULL,
	"rate_key" text NOT NULL,
	"network_key" text NOT NULL,
	"created_at" text NOT NULL,
	"updated_at" text NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "studio_enquiries_reference_unique" ON "studio_enquiries" ("reference");
CREATE INDEX IF NOT EXISTS "enquiry_created" ON "studio_enquiries" ("created_at");
CREATE INDEX IF NOT EXISTS "enquiry_email_rate" ON "studio_enquiries" ("rate_key","created_at");
CREATE INDEX IF NOT EXISTS "enquiry_network_rate" ON "studio_enquiries" ("network_key","created_at");
CREATE UNIQUE INDEX IF NOT EXISTS "enquiry_confirmed_slot" ON "studio_enquiries" ("preferred_date","preferred_time") WHERE "studio_enquiries"."status" = 'confirmed';
CREATE TABLE IF NOT EXISTS "studio_limits" (
	"id" text PRIMARY KEY NOT NULL,
	"count" integer NOT NULL,
	"expires_at" integer NOT NULL
);

CREATE TABLE IF NOT EXISTS "studio_payments" (
	"id" text PRIMARY KEY NOT NULL,
	"reference" text NOT NULL,
	"title" text NOT NULL,
	"amount_paise" integer NOT NULL,
	"status" text DEFAULT 'requested' NOT NULL,
	"checkout_url" text NOT NULL,
	"token" text NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"created_at" text NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "studio_payments_token_unique" ON "studio_payments" ("token");
CREATE TABLE IF NOT EXISTS "studio_ai_settings" (
	"id" integer PRIMARY KEY NOT NULL,
	"provider" text DEFAULT 'gemini' NOT NULL,
	"model" text NOT NULL,
	"key_ciphertext" text DEFAULT '' NOT NULL,
	"key_iv" text DEFAULT '' NOT NULL,
	"version" integer DEFAULT 0 NOT NULL,
	"updated_at" text NOT NULL,
	"updated_by" text NOT NULL
);

ALTER TABLE veloryz_studio.cms_admins ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.cms_admins TO service_role;
ALTER TABLE veloryz_studio.cms_history ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.cms_history TO service_role;
ALTER TABLE veloryz_studio.cms_media ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.cms_media TO service_role;
ALTER TABLE veloryz_studio.cms_state ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.cms_state TO service_role;
ALTER TABLE veloryz_studio.studio_enquiries ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.studio_enquiries TO service_role;
ALTER TABLE veloryz_studio.studio_limits ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.studio_limits TO service_role;
ALTER TABLE veloryz_studio.studio_payments ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.studio_payments TO service_role;
ALTER TABLE veloryz_studio.studio_ai_settings ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON veloryz_studio.studio_ai_settings TO service_role;
