INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES ('veloryz-studio','veloryz-studio',false,26214400,ARRAY['image/png','image/jpeg','image/webp','image/gif','image/avif','video/mp4','video/webm']) ON CONFLICT(id) DO NOTHING;
